test('received local days account for DST and extreme time zones',()=>{
 const rome=dates.receivedRange('2026-11-22','2026-11-22','Europe/Rome');assert.equal(new Date(rome.start).toISOString(),'2026-11-21T23:00:00.000Z');assert.equal(new Date(rome.end).toISOString(),'2026-11-22T23:00:00.000Z');
 for(const [day,hours]of[['2026-03-29',23],['2026-10-25',25]]){const r=dates.receivedRange(day,day,'Europe/Rome');assert.equal((r.end-r.start)/3600000,hours);}
 assert.equal(new Date(dates.receivedRange('2026-11-22','2026-11-22','Pacific/Kiritimati').start).toISOString(),'2026-11-21T10:00:00.000Z');assert.throws(()=>dates.receivedRange('2026-11-22','2026-11-22','Invalid/Zone'));assert.throws(()=>dates.receivedRange('2026-02-30','2026-02-30','UTC'));
});
test('same-day 22 November search filters full received-day boundaries on every page',async()=>{
 const h=harness(),range=dates.receivedRange('2026-11-22','2026-11-22','Europe/Rome');let query;
 const samples=[range.start-1,range.start,range.end-1,range.end].map((date,i)=>({...message('Hotel confirmation\nPNR: ABC123\nHotel: Example Stay\nOperator: Example Hotel\nAddress: Roma\nCheck-in: 2027-01-02T15:00+01:00'),id:'sample'+i,internalDate:String(date)}));
 h.setFetch(async u=>{if(u.includes('/messages?')){const p=new URL(u).searchParams;query=p.get('q');return new Response(JSON.stringify({messages:(p.has('pageToken')?samples.slice(2):samples.slice(0,2)).map(m=>({id:m.id})),...(!p.has('pageToken')?{nextPageToken:'page-two'}:{})}));}return new Response(JSON.stringify(samples.find(m=>u.includes('/'+m.id+'?'))));});
 const input={from:'2026-11-22',to:'2026-11-22',timeZone:'Europe/Rome'},first=await h.server.searchGmail(h.user,input);assert.equal(first.examined,1);assert.equal(first.outsideRange,1);assert.equal(first.candidates.length,1);assert.equal(first.candidates[0].email.date,new Date(range.start).toISOString());assert(query.includes(`after:${range.start/1000-1}`));assert(query.includes(`before:${range.end/1000}`));
 const second=await h.server.searchGmail(h.user,{...input,cursor:first.nextCursor});assert.equal(second.examined,1);assert.equal(second.outsideRange,1);assert.equal(second.candidates.length,0);assert.equal(second.duplicates,1);assert.equal(second.nextCursor,null);assert.equal(h.bookings.length,0);
 await assert.rejects(()=>h.server.searchGmail(h.user,{...input,timeZone:'UTC',cursor:first.nextCursor}));await assert.rejects(()=>h.server.searchGmail(h.user,{...input,to:'2026-11-23',cursor:first.nextCursor}));
});
