const bookingForwardHtml=require('./fixtures/gmail-booking-forward.cjs');
function bookingForwardMessage(){const m=message(bookingForwardHtml(),{html:true,subject:'Fwd: Grazie! La tua prenotazione per Studio Aurora di Prova è confermata'});m.id='syntheticbooking';m.internalDate=String(Date.parse('2026-11-22T12:00:00Z'));return m;}
async function searchSynthetic(h,messages){h.setFetch(async u=>{if(u.includes('/messages?'))return new Response(JSON.stringify({messages:messages.map(m=>({id:m.id}))}));return new Response(JSON.stringify(messages.find(m=>u.includes('/messages/'+m.id+'?'))));});return h.server.searchGmail(h.user,{from:'2026-11-21',to:'2026-11-23',timeZone:'Europe/Rome'});}
test('hotfix: Booking forwarded HTML recognizes split reference, subject property, dates and excludes PIN',()=>{
 const c=parser.parseGmailMessage(bookingForwardMessage())[0];assert(c);assert.equal(c.draft.provider,'Booking.com');assert.equal(c.draft.title,'Hotel Studio Aurora di Prova');assert.equal(c.draft.reference,'8642135790');assert.equal(c.draft.location,'Via Sintetica 8, 9000 Villaggio Esempio, Norvegia');assert.equal(c.draft.startDate,'2027-01-10T15:00+01:00');assert.equal(c.draft.endDate,'2027-01-11T12:00+01:00');assert.equal(c.timing.start.qualifier,'after');assert.equal(c.timing.end.qualifier,'before');assert(c.draft.notes.includes('Ospiti: 2 adulti'));assert(c.draft.notes.includes('Camera matrimoniale'));assert(c.draft.notes.includes('NOK 1.700'));assert.equal(c.event,'confirmation');assert(!JSON.stringify(c).includes('7319'));assert(!parser.messageBodies(bookingForwardMessage()).text.includes('7319'));
});
test('hotfix: original Booking message and forwarded confirmation remain distinct from a newsletter',()=>{
 const m=bookingForwardMessage();m.payload.headers=m.payload.headers.filter(h=>h.name!=='From');m.payload.headers.push({name:'From',value:'Booking.com <noreply@booking.com>'},{name:'Authentication-Results',value:'mx.google.com; dkim=pass header.d=booking.com'});assert.equal(parser.parseGmailMessage(m)[0].draft.provider,'Booking.com');
 const diagnostic={};assert.equal(parser.parseGmailMessage(message('Booking.com <noreply@booking.com>\nOfferte per il tuo prossimo viaggio!\nPIN: 7319',{subject:'Booking.com: scopri le offerte'}),diagnostic).length,0);assert.equal(diagnostic.excluded,'missing_reference');assert.equal(parser.parseGmailMessage(message('Booking.com <noreply@booking.com>\nNumero di conferma: 1234567890',{subject:'Fwd: Citazione Booking.com'}),{}).length,0);
});
test('hotfix: 21–23 November receipt window returns both forwarded Airbnb and Booking confirmations',async()=>{
 const h=harness(),a=syntheticStayMessage(),b=bookingForwardMessage();a.internalDate=String(Date.parse('2026-11-22T09:00:00Z'));const p=await searchSynthetic(h,[a,b]);assert.equal(p.examined,2);assert.equal(p.candidates.length,2);assert.equal(p.candidates.map(c=>c.draft.provider).sort().join(','),'Airbnb,Booking.com');assert.equal(h.bookings.length,0);assert(!JSON.stringify(p).includes('7319'));
});
test('hotfix: import/delete/search/reimport reclaims only matching orphan ledger and is idempotent concurrently',async()=>{
 const h=harness(),m=bookingForwardMessage();let row=(await searchSynthetic(h,[m])).candidates[0];const choice={token:row.token,draft:row.draft,tripId:'trip',action:'create'};await h.server.importGmail(h.user,{confirm:true,choices:[choice]});const oldId=h.bookings[0].id;row=(await searchSynthetic(h,[m])).candidates[0];assert.equal(row.state,'Già presente');assert.equal(row.matches[0].tripName,'Londra');await h.db.booking.deleteMany({where:{id:oldId}});assert.equal(h.ledger.length,1);row=(await searchSynthetic(h,[m])).candidates[0];assert.notEqual(row.state,'Già presente');assert.equal(row.matches.length,0);
 const reimport={...choice,token:row.token,draft:row.draft};const results=await Promise.all([h.server.importGmail(h.user,{confirm:true,choices:[reimport]}),h.server.importGmail(h.user,{confirm:true,choices:[reimport]})]);assert.equal(h.bookings.length,1);assert.notEqual(h.bookings[0].id,oldId);assert.equal(h.ledger.length,1);assert(results.some(r=>r.results[0].status==='saltata: già presente'));assert.equal((await searchSynthetic(h,[m])).candidates[0].state,'Già presente');
});
test('hotfix: stale preview from before deletion can reimport, other user/account/unrelated history is preserved',async()=>{
 const h=harness(),c=h.choice();await h.server.importGmail(h.user,{confirm:true,choices:[c]});await h.db.booking.deleteMany({where:{id:h.bookings[0].id}});const orphan={...h.ledger[0]};h.ledger.push({...orphan,id:'foreign-user',user_id:'bob'}, {...orphan,id:'foreign-account',account_hash:'other'}, {...orphan,id:'unrelated',source_key:'unrelated',fingerprint:'unrelated',reference_key:'unrelated'});const r=await h.server.importGmail(h.user,{confirm:true,choices:[c]});assert.equal(r.results[0].status,'importata');assert.equal(h.ledger.length,4);assert(h.ledger.some(r=>r.id==='foreign-user'));assert(h.ledger.some(r=>r.id==='foreign-account'));assert(h.ledger.some(r=>r.id==='unrelated'));
});
test('hotfix: same user cannot create a duplicate in another accessible trip, even with another message/account ledger',async()=>{
 const h=harness();h.trips.push({...h.trips[0],id:'trip2',name:'Altro viaggio'});await h.server.importGmail(h.user,{confirm:true,choices:[h.choice()]});h.ledger.splice(0);const r=await h.server.importGmail(h.user,{confirm:true,choices:[{...h.choice({key:'different-message'}),tripId:'trip2'}]});assert.equal(r.results[0].status,'non importata');assert.equal(h.bookings.length,1);
});
test('hotfix: unrelated user bookings neither appear in preview nor block this user import',async()=>{
 const h=harness(),m=bookingForwardMessage(),d=parser.parseGmailMessage(m)[0].draft;h.trips.push({...h.trips[0],id:'bob-trip',ownerId:'bob'});await h.db.booking.create({data:{...d,id:'foreign-booking',tripId:'bob-trip',startDate:new Date(d.startDate),endDate:new Date(d.endDate)}});const row=(await searchSynthetic(h,[m])).candidates[0];assert.equal(row.matches.length,0);assert.notEqual(row.state,'Già presente');const result=await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});assert.equal(result.results[0].status,'importata');assert.equal(h.bookings.length,2);
});

test('hotfix: deletion after a matched preview does not leave stale signed matches as a permanent blocker',async()=>{
 const h=harness(),m=bookingForwardMessage();let row=(await searchSynthetic(h,[m])).candidates[0];await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});row=(await searchSynthetic(h,[m])).candidates[0];assert.equal(row.matches.length,1);await h.db.booking.deleteMany({where:{id:h.bookings[0].id}});const result=await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});assert.equal(result.results[0].status,'importata');assert.equal(h.bookings.length,1);
});
test('hotfix: a live mapping outside current trip access is never pruned or exposed as a destination',async()=>{
 const h=harness(),m=bookingForwardMessage();let row=(await searchSynthetic(h,[m])).candidates[0];await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});h.trips[0].ownerId='bob';h.trips[0].name='Private destination';h.trips.push({...h.trips[0],id:'trip2',ownerId:'alice',name:'Accessible'});row=(await searchSynthetic(h,[m])).candidates[0];assert.equal(row.matches.length,0);assert(!JSON.stringify(row).includes('Private destination'));const r=await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip2',action:'create'}]});assert.equal(r.results[0].status,'saltata: già presente');assert.equal(h.bookings.length,1);assert.equal(h.ledger.length,1);
});

test('Booking forwarded complete pipeline produces an importable preview and saved itinerary without PIN',async()=>{
 const h=harness(),m=bookingForwardMessage();const row=(await searchSynthetic(h,[m])).candidates[0];assert.notEqual(row.state,'Già presente');assert.equal(row.event,'confirmation');assert.equal(row.timing.start.zone,'Europe/Oslo');const valid=core.validateDraft(row.draft);assert(valid.startDate);assert(valid.endDate);const proof=h.cipher.open(row.token,'preview:alice');assert(!JSON.stringify(proof).includes('7319'));
 const result=await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});assert.equal(result.results[0].status,'importata');assert.equal(h.activities.length,2);assert.equal(h.activities[0].time,'15:00');assert(h.bookings[0].notes.includes('dopo le 15:00'));assert.equal(h.bookings[0].startDate.toISOString(),'2027-01-10T14:00:00.000Z');
});
test('MIME diagnostic distinguishes skipped named HTML, unsupported forwarded attachments and truncation',()=>{
 const named=bookingForwardMessage();named.payload.filename='forward.html';const d={};assert.equal(parser.parseGmailMessage(named,d).length,0);assert(d.mimeIssues.includes('mime_text_attachment_skipped'));assert(d.mimeIssues.includes('mime_text_absent'));
 const nested=message('');nested.payload={mimeType:'message/rfc822',filename:'forward.eml',body:{data:Buffer.from('synthetic').toString('base64url')}};const r={};parser.parseGmailMessage(nested,r);assert(r.mimeIssues.includes('mime_rfc822_unsupported'));
 const huge=message('x'.repeat(210000));const t={};parser.parseGmailMessage(huge,t);assert(t.mimeIssues.includes('mime_text_truncated'));
});

function trainMessage(id,{passenger='Persona sintetica A',from='Roma Termini',to='Milano Centrale',service='9999',event='confirmation'}={}){
 const m=message(`Italo <booking@italotreno.it>\nPNR: TRAINTEST2027\nStazione partenza: ${from}\nStazione arrivo: ${to}\nPartenza: 2027-01-10T15:00+01:00\nArrivo: 2027-01-10T18:00+01:00\nNumero treno: ${service}\nPasseggeri: ${passenger}`,{subject:event==='change'?'Orario modificato - prenotazione confermata':'Conferma prenotazione Italo'});m.id=id;m.internalDate=String(Date.parse('2026-11-22T12:00:00Z'));return m;
}
test('rail duplicates across emails/pages collapse while different routes, services and passengers survive',async()=>{
 const h=harness(),a=trainMessage('railA'),duplicate=trainMessage('railB'),other=trainMessage('railC',{from:'Roma Termini',to:'Napoli Centrale',service:'8888'});
 h.setFetch(async u=>{if(u.includes('/messages?'))return new Response(JSON.stringify(new URL(u).searchParams.has('pageToken')?{messages:[{id:duplicate.id},{id:other.id}]}:{messages:[{id:a.id},{id:duplicate.id}],nextPageToken:'next'}));return new Response(JSON.stringify([a,duplicate,other].find(m=>u.includes('/messages/'+m.id+'?'))));});
 const input={from:'2026-11-21',to:'2026-11-23',timeZone:'Europe/Rome'},first=await h.server.searchGmail(h.user,input),second=await h.server.searchGmail(h.user,{...input,cursor:first.nextCursor});assert.equal(first.candidates.length,1);assert.equal(first.duplicates,1);assert.equal(second.candidates.length,1);assert.equal(second.duplicates,1);assert.notEqual(first.candidates[0].identityKey,second.candidates[0].identityKey);
 const pax=trainMessage('railD',{passenger:'Persona sintetica B'}),p=await searchSynthetic(h,[a,pax,other]);assert.equal(p.candidates.length,3);for(const row of p.candidates){const result=await h.server.importGmail(h.user,{confirm:true,choices:[{token:row.token,draft:row.draft,tripId:'trip',action:'create'}]});assert.equal(result.results[0].status,'importata');}assert.equal(h.bookings.length,3);const again=await searchSynthetic(h,[duplicate]);assert.equal(again.candidates[0].state,'Già presente');assert.equal(h.bookings.length,3);
});
test('train identities retain individual names when a passenger count is also present',()=>{
 const d={...draft(),type:'train',notes:'Numero treno: 9999\nPasseggeri: 1\nIntestatario: Persona A',originAirport:'Roma Termini',destinationAirport:'Milano Centrale'};
 const a=core.candidateKeys({draft:d,event:'confirmation',warnings:[]}),b=core.candidateKeys({draft:{...d,notes:d.notes.replace('Persona A','Persona B')},event:'confirmation',warnings:[]});assert.notEqual(a.fingerprint,b.fingerprint);
});
test('reference-only flight is excluded from preview and rejected by confirmation validation',async()=>{
 const h=harness(),m=message('Flight confirmation\nPNR: EMPTYFLIGHT');m.internalDate=String(Date.parse('2026-11-22T12:00Z'));const parsed=parser.parseGmailMessage(m)[0];assert.equal(core.previewQuality(parsed),'Non riconosciuta');const p=await searchSynthetic(h,[m]);assert.equal(p.examined,1);assert.equal(p.candidates.length,0);assert.equal(p.excluded.insufficient_details,1);await assert.rejects(()=>h.server.importGmail(h.user,{confirm:true,choices:[h.choice({candidate:parsed})]}),e=>e.status===400);assert.equal(h.bookings.length,0);
});
test('quality distinguishes complete Booking from credible partial and an isolated number',()=>{
 const complete=parser.parseGmailMessage(bookingForwardMessage())[0];assert.equal(core.previewQuality(complete),'Importabile');const partial={...complete,draft:{...complete.draft,startDate:'',endDate:''}};assert.equal(core.previewQuality(partial),'Da verificare');assert.equal(parser.parseGmailMessage(message('Numero generico: 1234567890')).length,0);
});

test('explicit rail update matches the same passenger/route when service details change',async()=>{
 const h=harness(),first=(await searchSynthetic(h,[trainMessage('original-rail')])).candidates[0];await h.server.importGmail(h.user,{confirm:true,choices:[{token:first.token,draft:first.draft,tripId:'trip',action:'create'}]});const id=h.bookings[0].id,changed=(await searchSynthetic(h,[trainMessage('changed-rail',{service:'7777',event:'change'})])).candidates[0];assert.equal(changed.event,'change');assert.equal(changed.matches[0].id,id);const r=await h.server.importGmail(h.user,{confirm:true,choices:[{token:changed.token,draft:changed.draft,tripId:'trip',action:'update',bookingId:id}]});assert.equal(r.results[0].status,'aggiornata');assert.equal(h.bookings.length,1);assert.equal(h.bookings[0].id,id);
});

test('partial preview identity ignores wording differences but preserves extracted civil date/time',()=>{
 const a={draft:{...draft(),type:'train',startDate:'',endDate:'',notes:'Numero treno: 9999\nPasseggeri: Persona sintetica'},event:'confirmation',warnings:[],timing:{start:dates.parseMailTime('10 gennaio 2027 15:00'),end:dates.emptyMailTime()}};
 const b={...a,timing:{...a.timing,start:{...a.timing.start,raw:'Sunday 10 January 2027 at 15:00'}}};assert.equal(core.candidateKeys(a).fingerprint,core.candidateKeys(b).fingerprint);assert.notEqual(core.candidateKeys(a).fingerprint,core.candidateKeys({...b,timing:{...b.timing,start:{...b.timing.start,time:'16:00'}}}).fingerprint);
});



test('Booking short Conferma label in forwarded complex HTML produces importable preview without PIN',async()=>{
 const m=bookingForwardMessage();m.payload.body.data=Buffer.from(bookingForwardHtml({shortLabel:true})).toString('base64url');const diagnostic={};const parsed=parser.parseGmailMessage(m,diagnostic);assert.equal(diagnostic.excluded,undefined);assert.equal(parsed[0].draft.reference,'8642135790');assert.equal(core.previewQuality(parsed[0]),'Importabile');assert(!/73\s*19/.test(JSON.stringify(parsed)));assert(!/73\s*19/.test(parser.messageBodies(m).text));
 const h=harness(),result=await searchSynthetic(h,[m]);assert.equal(result.candidates.length,1);const row=result.candidates[0];assert.equal(row.state,'Importabile');assert.equal(row.draft.reference,'8642135790');assert(!/73\s*19/.test(JSON.stringify(row)));assert.equal(core.validateDraft(row.draft).reference,'8642135790');const proof=h.cipher.open(row.token,`preview:${h.user.id}`);assert(!/73\s*19/.test(JSON.stringify(proof)));assert.equal(h.bookings.length,0);
});
for(const separator of [': ',':\n', '\n', '\n:\n', '：\n', '# ', '= '])test(`Booking short label supports separator ${JSON.stringify(separator)}`,()=>{const m=bookingForwardMessage();m.payload.body.data=Buffer.from(bookingForwardHtml().replace(/<tr><td>Numero di conferma:[\s\S]*?<\/tr>/,'<tr><td>Conferma'+separator+'<span>8642</span>&#8239;<span>135</span><br>790 PIN: 7319</td></tr>')).toString('base64url');assert.equal(parser.parseGmailMessage(m)[0].draft.reference,'8642135790');});
test('Booking short reference rejects generic numbers, PIN-only, dates, short/long and foreign-provider labels',()=>{for(const body of ['Telefono: 8642135790','Conferma: PIN: 7319','Conferma: 7319','Conferma: 2027.01.10','Conferma: 10 01 2027','Conferma: 123456789012345','Conferma: +47 12345678','Conferma: 12345678 euro']){const m=message('Booking.com <noreply@booking.com>\nLa tua prenotazione è confermata.\n'+body);assert.equal(parser.parseGmailMessage(m).length,0,body);}assert.equal(parser.parseGmailMessage(message('Hotel confirmation\nConferma: 8642135790')).length,0);});
test('removed incident diagnostic rejects stale activation before any Gmail access',async()=>{const h=harness({diagnostics:true});await assert.rejects(()=>h.server.searchGmail(h.user,{from:'2026-11-21',to:'2026-11-23',timeZone:'Europe/Rome',diagnoseTarget:true}),e=>e.status===400);assert.equal(h.calls.length,0);const status=await h.server.gmailStatus(h.user);assert.equal(status.targetDiagnosticAvailable,undefined);});

const bookingAddressHtml=require('./fixtures/gmail-booking-address.cjs');
function bookingAddressMessage(options){const m=message(bookingAddressHtml(options),{html:true,subject:'Fwd: prenotazione confermata'});m.internalDate=String(Date.parse('2026-11-22T10:00Z'));return m;}
for(const inline of [true,false])test(`Booking unlabelled postal address and ${inline?'inline':'table'} dates preserve Oslo stay limits`,()=>{const c=parser.parseGmailMessage(bookingAddressMessage({inline}))[0];assert.equal(c.draft.location,'Via Aurora di Prova 42, 9050 Borgo Esempio, Norvegia');assert.equal(c.timing.start.zone,'Europe/Oslo');assert.equal(c.draft.startDate,'2027-01-14T15:00+01:00');assert.equal(c.draft.endDate,'2027-01-16T12:00+01:00');assert.equal(c.timing.start.qualifier,'after');assert.equal(c.timing.end.qualifier,'before');assert.equal(core.previewQuality(c),'Importabile');assert.doesNotThrow(()=>core.validateDraft(c.draft));});
test('Booking address -> timezone -> unique country/date trip -> explicit synthetic save',async()=>{const h=harness();h.trips.push({...h.trips[0],id:'north',name:'Nord 2027',city:'Tromsø',country:'Norway',startDate:new Date('2027-01-01'),endDate:new Date('2027-01-30')});const result=await searchSynthetic(h,[bookingAddressMessage()]);const r=result.candidates[0];assert.equal(r.state,'Importabile');assert.equal(r.suggestedTripId,'north');assert.equal(h.bookings.length,0);const incomplete={...r.draft,startDate:'',endDate:''};assert.throws(()=>core.validateDraft(incomplete),/date e fusi/);const saved=await h.server.importGmail(h.user,{confirm:true,choices:[{token:r.token,draft:r.draft,tripId:r.suggestedTripId,action:'create'}]});assert.equal(saved.results[0].status,'importata');assert.equal(h.bookings[0].tripId,'north');assert.equal(h.bookings[0].location,r.draft.location);});
test('country aliases generalize beyond Norway, reject country conflicts and preserve ambiguous selection',()=>{for(const [country,english]of [['Italia','Italy'],['Francia','France'],['Germania','Germany']]){const d={...draft(),location:`Via Esempio 42, 10100 Borgo, ${country}`,destinationAirport:''};const t={id:'local',name:'Viaggio sintetico',city:'Altra città',country:english,startDate:'2027-01-01',endDate:'2027-01-20'};assert.equal(core.suggestTrip(d,[t]),'local');assert.equal(core.suggestTrip(d,[t,{...t,id:'tie'}]),null);assert.equal(core.suggestTrip(d,[{...t,endDate:'2027-01-01'}]),null);assert.equal(core.suggestTrip(d,[{...t,country:'Norway',city:'Borgo'}]),null);}});
test('unlabelled Booking addresses do not infer from footer, phone, numbers or conflicting addresses',()=>{for(const replacement of ['Telefono: 123456789','Sede legale: Via Esempio 42, 9050 Borgo, Norvegia','<img alt="Via Esempio 42, 9050 Borgo, Norvegia">','<p>Via A 42, 9050 Borgo, Norvegia</p><p>Via B 51, 9051 Altro, Norvegia</p>']){const m=bookingAddressMessage();const html=bookingAddressHtml().replace(/<p><a[\s\S]*?<\/a><\/p>/,replacement);m.payload.body.data=Buffer.from(html).toString('base64url');const c=parser.parseGmailMessage(m)[0];assert.equal(c.draft.location,'');assert.equal(c.timing.start.offset,'');assert.equal(c.draft.startDate,'');}});

test('Booking address components split across spans/blocks retain postal country and Oslo',()=>{const m=bookingAddressMessage();const html=bookingAddressHtml().replace(/<p><a[\s\S]*?<\/a><\/p>/,'<div>Via Aurora di Prova</div><div>42,</div><div>9050</div><div>Borgo Esempio,</div><div>Norvegia</div>');m.payload.body.data=Buffer.from(html).toString('base64url');const c=parser.parseGmailMessage(m)[0];assert(c.draft.location.includes('9050 Borgo Esempio'));assert.equal(c.timing.start.zone,'Europe/Oslo');});
